import React from 'react';
import { useParams, Link } from 'react-router-dom';

// Mock data for a single note's details. In a real app, this would be fetched from the backend.
const mockNoteDetails = {
    id: 'N-001',
    title: 'Request for New Conference Speakers',
    initiator: 'Dr. Anjali Rao',
    department: 'Computer Science',
    submittedDate: '2025-10-25',
    description: 'Proposal to allocate budget for inviting three guest speakers for the upcoming National Conference on AI. The estimated cost is ₹1,50,000.',
    // This is the approval chain
    approvals: [
        { role: 'Campus Admin', status: 'Approved', date: '2025-10-25', approver: 'Mr. Sharma' },
        { role: 'Finance Officer', status: 'Pending', date: null, approver: null },
        { role: 'Registrar', status: 'Pending', date: null, approver: null },
        { role: 'Vice Chancellor', status: 'Pending', date: null, approver: null },
    ]
};

const NoteDetailsPage = () => {
    const { noteId } = useParams(); // Gets the 'N-001' from the URL

    // Helper to get styling for approval statuses
    const getStatusIcon = (status) => {
        switch (status) {
            case 'Approved': return <span className="material-icons text-green-500">check_circle</span>;
            case 'Pending': return <span className="material-icons text-yellow-500">pending</span>;
            case 'Rejected': return <span className="material-icons text-red-500">cancel</span>;
            default: return null;
        }
    };

    return (
        <div className="p-8">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">{mockNoteDetails.title}</h1>
                    <p className="text-sm text-subtext-light">Submitted by {mockNoteDetails.initiator} on {mockNoteDetails.submittedDate}</p>
                </div>
                <Link to="/notes-approvals" className="text-primary hover:underline text-sm font-medium">&larr; Back to List</Link>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                {/* Left Column: Document Viewer */}
                <div className="lg:col-span-2 bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm">
                    <h3 className="text-lg font-semibold mb-4">Submitted Document</h3>
                    <div className="border rounded-lg p-4 bg-background-light min-h-[600px]">
                        {/* In a real app, you would use a PDF viewer library here */}
                        <p className="text-subtext-light">[This is where the uploaded PDF document would be displayed]</p>
                        <p className="mt-4">{mockNoteDetails.description}</p>
                    </div>
                </div>

                {/* Right Column: Approval Workflow */}
                <div className="lg:col-span-1 bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm">
                    <h3 className="text-lg font-semibold mb-4">Approval Chain</h3>
                    <ul className="space-y-6">
                        {mockNoteDetails.approvals.map((approval) => (
                            <li key={approval.role} className="flex items-center space-x-4">
                                <div>{getStatusIcon(approval.status)}</div>
                                <div>
                                    <p className="font-semibold text-text-light dark:text-text-dark">{approval.role}</p>
                                    <p className="text-xs text-subtext-light">
                                        {approval.status === 'Pending' ? 'Awaiting approval' : `Approved by ${approval.approver} on ${approval.date}`}
                                    </p>
                                </div>
                            </li>
                        ))}
                    </ul>
                    {/* Action buttons for the current user would go here */}
                    <div className="border-t mt-6 pt-4 flex space-x-2">
                         <button className="bg-green-500 text-white px-4 py-2 rounded-lg text-sm w-full">Approve</button>
                         <button className="bg-red-500 text-white px-4 py-2 rounded-lg text-sm w-full">Reject</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default NoteDetailsPage;
